import * as React from "react";
import { headers } from "next/headers";

/**
 * Auth route-group layout (`/login`, `/register`, `/verify-email`,
 * `/forgot-password`, `/reset-password`).
 *
 * Reads the per-request `x-nonce` header generated by `src/proxy.ts` so that
 * auth pages loading Cloudflare Turnstile render dynamically with the
 * per-request nonce CSP while informational pages remain statically rendered.
 */
export default async function AuthGroupLayout({
  children,
}: {
  children: React.ReactNode;
}) {
  const headerList = await headers();
  const nonce = headerList.get("x-nonce") ?? undefined;

  return (
    <div data-csp-mode="nonce" data-nonce-present={nonce ? "true" : "false"}>
      {children}
    </div>
  );
}
